@pytest.fixture
def registry(isolated_env):
    """Provide a clean registry instance per test."""
    return isolated_env["registry"]


def _random_factory(seed):
    """Deterministic pseudo-random factory for stress tests."""
    rng = random.Random(seed)
    return {
        "id": seed,
        "payload": "".join(rng.choices(string.ascii_letters, k=16)),
        "timestamp": rng.randint(0, 2**32),
    }


def _nested_factory(seed):
    """Factory producing deeply nested structures to test deepcopy integrity."""
    return {
        "level1": {
            "level2": {
                "level3": [seed, {"nested": True}],
            }
        }
    }


