@pytest.mark.unit
class TestMockRegistryLifecycle:
    """Comprehensive lifecycle validation."""

    def test_registry_creates_fresh_mocks(self, isolated_env):
        """Each create call returns a new instance (identity check)."""
        registry = isolated_env["registry"]

        mock1 = registry.create("test", factory=lambda seed: {"seed": seed})
        mock2 = registry.create("test", factory=lambda seed: {"seed": seed})

        assert mock1 is not mock2
        assert mock1["seed"] != mock2["seed"]

    def test_registry_create_without_factory(self, registry):
        """Creating without a factory should raise a clear error."""
        with pytest.raises(TypeError, match="factory"):
            registry.create("no_factory")

    def test_registry_create_with_none_factory(self, registry):
        """Explicit None factory should be rejected."""
        with pytest.raises(TypeError, match="factory"):
            registry.create("none_factory", factory=None)

    def test_registry_create_invalid_name(self, registry):
        """Empty or whitespace-only names must be rejected."""
        for invalid_name in ["", "   ", "\t\n"]:
            with pytest.raises(ValueError, match="name"):
                registry.create(invalid_name, factory=lambda seed: seed)

    def test_registry_create_duplicate_name(self, registry):
        """Duplicate names should either overwrite or raise; we enforce raise."""
        registry.create("dup", factory=lambda seed: seed)
        with pytest.raises(KeyError, match="dup"):
            registry.create("dup", factory=lambda seed: seed)

    def test_registry_snapshot_restore(self, isolated_env):
        """Snapshot and restore maintains deep state integrity."""
        registry = isolated_env["registry"]
        mock = registry.create("test", factory=lambda seed: {"value": 0})
        mock["value"] = 42

        snapshot = registry.snapshot()
        mock["value"] = 99

        registry.restore(snapshot)
        assert mock["value"] == 42

    def test_registry_snapshot_restore_nested(self, registry):
        """Snapshot/restore must handle nested mutable structures."""
        mock = registry.create("nested", factory=_nested_factory)
        original_nested = deepcopy(mock)

        # Mutate deeply
        mock["level1"]["level2"]["level3"].append("corrupted")

        snapshot = registry.snapshot()
        registry.restore(snapshot)

        # Verify deep equality
        assert mock == original_nested

    def test_registry_snapshot_restore_multiple_mocks(self, registry):
        """Snapshot captures all registered mocks, not just one."""
        mocks = {}
        for i in range(10):
            mocks[f"mock_{i}"] = registry.create(
                f"mock_{i}", factory=lambda seed: {"value": seed}
            )
            mocks[f"mock_{i}"]["value"] = i * 10

        snapshot = registry.snapshot()

        # Corrupt all
        for mock in mocks.values():
            mock["value"] = -1

        registry.restore(snapshot)

        for i, mock in mocks.items():
            assert mock["value"] == int(i.split("_")[1]) * 10

    def test_registry_reset_all(self, isolated_env):
        """Reset returns all mocks to initial state."""
        registry = isolated_env["registry"]
        mock = registry.create("test", factory=lambda seed: {"value": 0})
        mock["value"] = 42

        registry.reset_all()
        assert mock["value"] == 0

    def test_registry_reset_all_multiple(self, registry):
        """Reset must affect all mocks, not just the most recent."""
        mocks = []
        for i in range(5):
            m = registry.create(f"m{i}", factory=lambda seed: {"value": seed})
            m["value"] = 100 + i
            mocks.append(m)

        registry.reset_all()

        for i, m in enumerate(mocks):
            assert m["value"] == i  # factory returns seed

    def test_registry_reset_all_after_snapshot(self, registry):
        """Reset should not affect snapshot integrity."""
        mock = registry.create("test", factory=lambda seed: {"value": 0})
        mock["value"] = 42

        snapshot = registry.snapshot()
        registry.reset_all()

        # Snapshot should still restore to the captured state
        registry.restore(snapshot)
        assert mock["value"] == 42


