@pytest.mark.stress
class TestMockRegistryStress:
    """Stress and property-based validation."""

    def test_registry_many_mocks_roundtrip(self, registry):
        """Create 1000 mocks, snapshot, corrupt, restore, verify all."""
        mocks = {}
        for i in range(1000):
            mocks[i] = registry.create(
                f"mock_{i}", factory=_random_factory
            )

        snapshot = registry.snapshot()

        # Corrupt all
        for mock in mocks.values():
            mock["payload"] = "CORRUPTED"

        registry.restore(snapshot)

        for i, mock in mocks.items():
            assert mock["payload"] != "CORRUPTED"
            assert mock["id"] == i

    def test_registry_concurrent_creation(self, registry):
        """Concurrent creation must not corrupt registry state."""
        async def create_mocks():
            tasks = []
            for i in range(100):
                tasks.append(asyncio.to_thread(
                    registry.create,
                    f"thread_{i}",
                    factory=_random_factory
                ))
            results = await asyncio.gather(*tasks)
            return results

        results = asyncio.run(create_mocks())
        assert len(results) == 100
        assert all(m["id"] == i for i, m in enumerate(results))

    def test_registry_snapshot_restore_under_load(self, registry):
        """Snapshot/restore under concurrent mutation must be atomic."""
        mock = registry.create("shared", factory=lambda seed: {"value": 0})

        async def mutate():
            for _ in range(100):
                mock["value"] += 1
                await asyncio.sleep(0)

        async def snapshot_loop():
            for _ in range(10):
                snap = registry.snapshot()
                await asyncio.sleep(0)
                registry.restore(snap)

        async def main():
            await asyncio.gather(mutate(), snapshot_loop())

        asyncio.run(main())

        # After all operations, value should be consistent (not necessarily 100,
        # but must be an integer and not corrupted)
        assert isinstance(mock["value"], int)
        assert 0 <= mock["value"] <= 100

    def test_registry_deepcopy_isolation(self, registry):
        """Mocks must be deep copies, not references to factory internals."""
        shared_state = {"counter": 0}

        def factory(seed):
            return {"state": shared_state, "seed": seed}

        mock1 = registry.create("m1", factory=factory)
        mock2 = registry.create("m2", factory=factory)

        # Mutating one mock's state should not affect the other
        mock1["state"]["counter"] = 42
        assert mock2["state"]["counter"] == 0


