@pytest.mark.failure
class TestMockRegistryFailureModes:
    """Validate graceful degradation and error propagation."""

    def test_registry_factory_raises(self, registry):
        """Factory exceptions must propagate with context."""
        def broken_factory(seed):
            raise RuntimeError(f"Factory failed for {seed}")

        with pytest.raises(RuntimeError, match="Factory failed"):
            registry.create("broken", factory=broken_factory)

    def test_registry_restore_invalid_snapshot(self, registry):
        """Restoring an invalid snapshot must raise a clear error."""
        with pytest.raises((TypeError, ValueError)):
            registry.restore(None)

        with pytest.raises((TypeError, ValueError)):
            registry.restore({"not": "a snapshot"})

    def test_registry_restore_after_reset(self, registry):
        """Restore after reset should still work (snapshot survives reset)."""
        mock = registry.create("test", factory=lambda seed: {"value": 0})
        mock["value"] = 42

        snapshot = registry.snapshot()
        registry.reset_all()
        registry.restore(snapshot)

        assert mock["value"] == 42

    def test_registry_restore_after_new_creation(self, registry):
        """Restoring should not break newly created mocks."""
        mock1 = registry.create("m1", factory=lambda seed: {"value": 0})
        mock1["value"] = 10
        snapshot = registry.snapshot()

        mock2 = registry.create("m2", factory=lambda seed: {"value": 0})
        mock2["value"] = 20

        registry.restore(snapshot)

        # mock1 should be restored, mock2 should remain untouched
        assert mock1["value"] == 10
        assert mock2["value"] == 20

    def test_registry_snapshot_empty(self, registry):
        """Snapshot of empty registry should be valid and restorable."""
        snapshot = registry.snapshot()
        registry.restore(snapshot)  # Should not raise

    def test_registry_reset_empty(self, registry):
        """Reset of empty registry should be a no-op."""
        registry.reset_all()  # Should not raise


