@pytest.mark.integration
class TestMockRegistryMessageIntegration:
    """Validate integration with Message/MessageType mocks."""

    def test_registry_with_message_factory(self, registry):
        """Registry should handle Message objects correctly."""
        def message_factory(seed):
            return Message(
                type=MessageType.DATA,
                payload={"seed": seed},
                sender="test",
                receiver="registry"
            )

        msg1 = registry.create("msg1", factory=message_factory)
        msg2 = registry.create("msg2", factory=message_factory)

        assert isinstance(msg1, Message)
        assert msg1 is not msg2
        assert msg1.payload["seed"] != msg2.payload["seed"]

    def test_registry_snapshot_with_messages(self, registry):
        """Snapshot/restore with Message objects must preserve state."""
        def message_factory(seed):
            return Message(
                type=MessageType.DATA,
                payload={"value": seed},
                sender="test",
                receiver="registry"
            )

        msg = registry.create("msg", factory=message_factory)
        msg.payload["value"] = 99

        snapshot = registry.snapshot()
        msg.payload["value"] = 0

        registry.restore(snapshot)
        assert msg.payload["value"] == 99

    def test_registry_reset_with_messages(self, registry):
        """Reset with Message objects must restore initial state."""
        def message_factory(seed):
            return Message(
                type=MessageType.DATA,
                payload={"value": seed},
                sender="test",
                receiver="registry"
            )

        msg = registry.create("msg", factory=message_factory)
        msg.payload["value"] = 42

        registry.reset_all()
        assert msg.payload["value"] == 0  # seed value


